'use client';
import { useEffect, useRef, useState } from 'react';

const BOXES = [
  { id: 1, top: '34%', left: '14%', width: '23%', height: '30%', label: 'NO PLATE', cls: 'bbox-r', tagCls: 'bbox-tag-r' },
  { id: 2, top: '38%', left: '57%', width: '20%', height: '26%', label: 'TRACKED',  cls: 'bbox-g', tagCls: 'bbox-tag-g' },
];

export default function LiveMonitor({ stream, isActive }) {
  const videoRef  = useRef(null);
  const [time, setTime]         = useState('');
  const [showBoxes, setShowBoxes] = useState(false);

  useEffect(() => {
    const tick = () => {
      const n = new Date();
      setTime(n.toLocaleTimeString('en-GB', { hour12: false }) + '.' + String(n.getMilliseconds()).padStart(3,'0').slice(0,2));
    };
    tick();
    const iv = setInterval(tick, 100);
    return () => clearInterval(iv);
  }, []);

  useEffect(() => {
    if (!videoRef.current) return;
    if (stream) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(() => {});
      setTimeout(() => setShowBoxes(true), 1400);
    } else {
      videoRef.current.srcObject = null;
      setShowBoxes(false);
    }
  }, [stream]);

  return (
    <div className="card" style={{ height: '100%' }}>
      <div className="card-head">
        <span className="card-title">Live CCTV Monitor</span>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {isActive && (
            <div className="rec">
              <div className="pulse-dot red" style={{ width: 5, height: 5 }} />
              REC
            </div>
          )}
          <span className="chip chip-n">CAM-01</span>
        </div>
      </div>

      <div className="card-body flex-col gap-10">
        {/* Monitor */}
        <div className="monitor-wrap">
          {/* Idle state */}
          {!isActive && (
            <div className="monitor-idle">
              <div className="monitor-idle-ico">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                  <rect x="2" y="4" width="20" height="14" rx="2" stroke="rgba(255,255,255,0.2)" strokeWidth="1.5"/>
                  <path d="M8 22h8M12 18v4" stroke="rgba(255,255,255,0.2)" strokeWidth="1.5" strokeLinecap="round"/>
                  <circle cx="12" cy="11" r="3" stroke="rgba(255,255,255,0.15)" strokeWidth="1.5"/>
                </svg>
              </div>
              <div className="monitor-idle-t1">No input signal</div>
              <div className="monitor-idle-t2">awaiting screen capture</div>
            </div>
          )}

          <video ref={videoRef} muted autoPlay playsInline
            style={{ display: isActive ? 'block' : 'none' }} />

          {/* Detection boxes */}
          {isActive && showBoxes && BOXES.map(b => (
            <div key={b.id} className={`bbox ${b.cls}`}
              style={{ top: b.top, left: b.left, width: b.width, height: b.height }}>
              <div className={`bbox-tag ${b.tagCls}`}>{b.label}</div>
            </div>
          ))}

          {/* Scan line */}
          {isActive && <div className="scanline" />}

          {/* Corners */}
          <div className="corner c-tl" /><div className="corner c-tr" />
          <div className="corner c-bl" /><div className="corner c-br" />

          {/* HUD */}
          <div className="hud hud-tl">CAM-001 · SECTOR-A</div>
          <div className="hud hud-tr">
            {isActive && <span style={{ color: 'var(--acc)' }}>30 FPS</span>}
            <span>MAIN FEED</span>
          </div>
          <div className="hud hud-bl">{time}</div>
          {isActive && <div className="hud hud-br">AI PROC · ACTIVE</div>}
        </div>

        {/* Mini stats */}
        {isActive && (
          <div className="monitor-stats">
            {[
              { v: '2',   l: 'Vehicles',   c: 'var(--t1)' },
              { v: '1',   l: 'No Plate',   c: 'var(--red)' },
              { v: '94%', l: 'Confidence', c: 'var(--acc)' },
            ].map(s => (
              <div className="m-stat" key={s.l}>
                <div className="m-stat-v" style={{ color: s.c }}>{s.v}</div>
                <div className="m-stat-l">{s.l}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
